import json

with open('/tmp/woo_products.json', 'r') as f:
    content = f.read()

# Split by product boundaries - each product has "id" at the top level
# Let's use a simple approach: find all occurrences of JSON objects
# by tracking brace depth
products = []
i = 0
while i < len(content):
    if content[i] == '{':
        depth = 0
        start = i
        while i < len(content):
            if content[i] == '{':
                depth += 1
            elif content[i] == '}':
                depth -= 1
                if depth == 0:
                    try:
                        obj = json.loads(content[start:i+1])
                        if 'id' in obj and 'sku' in obj:
                            products.append(obj)
                    except:
                        pass
                    break
            i += 1
    i += 1

for p in products:
    print(f"Woo ID={p['id']}, SKU={p['sku']}, stock={p.get('stock_quantity','?')}")

print(f"\nTotal products: {len(products)}")
PYEOF

